	public void ReleaseReferences()
	{
		try
		{
			if (base.Visible)
			{
				Close();
			}
			m_RulesIndexer = null;
			_MethodIndexer = null;
			_ServiceIndexer = null;
			SelectedMissionLink = null;
			observerResolver.Clear();
			TV_Missions.Nodes.Clear();
			TV_AssignedUnits.Nodes.Clear();
			TV_UnassignedUnits.Nodes.Clear();
			Combo_Escort_TargetMission.Items.Clear();
			Combo_Escort_TargetUnit.Items.Clear();
			ListBox_Targets.Items.Clear();
			DGV_Multimission.Items.Clear();
			List_CargoSources.Items.Clear();
			List_CargoItems.Items.Clear();
			AreaEditor_PatrolArea.ReleaseReferences();
			AreaEditor_ProsecutionArea.ReleaseReferences();
			AreaEditor_Support.ReleaseReferences();
			AreaEditor_Mining.ReleaseReferences();
			AreaEditor_MineClearing.ReleaseReferences();
			AreaEditor_Cargo.ReleaseReferences();
			EMCON_WRA_Mission = "";
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			ProjectData.ClearProjectError();
		}
	}

	protected override void OnShown(EventArgs e)
	{
		base.OnShown(e);
		ListBox_Targets.ContextMenuItem_Click += ListBox_Targets_ContextMenuItem_Click;
	}

	protected override bool ProcessCmdKey(ref Message m, Keys keyData)
	{
		Keys[] ruleResolver = _RuleResolver;
		Keys[] array = ruleResolver;
		foreach (Keys keys in array)
		{
			if (keyData == keys)
			{
				if (base.ActiveControl == null)
				{
					Activate();
				}
				else
				{
					Close();
				}
				return true;
			}
		}
		return false;
	}

