		{
			WriteInterruptibleConsumer();
			if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet != collectionResolver)
			{
				string[] array = new string[8] { "最小高度", "低 (1000 英尺)", "低 (2000 英尺)", "中 (12000 英尺)", "高 (25000 英尺)", "高 (36000 英尺)", "最大高度", "自定义高度" };
