				string[] array3;
				string[] array4;
				if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
				{
					array3 = array;
					array4 = array2;
				}
				else
				{
					array3 = array2;
					array4 = array;
				}
				foreach (DarkUIComboBox item in new List<DarkUIComboBox> { TransitAltitudeDropdown, AttackAltitudeDropdown, StationAltitudeDropdown, MiningStationAltitudeDropdown, MiningTransitAltitudeDropdown, SupportStationAltitudeDropdown, SupportTransitAltitudeDropdown, MineClearingStationAltitudeDropdown, MineClearingTransitAltitudeDropdown })
				{
					int num = array3.Count() - 1;
