	public void RefreshAll()
	{
		try
		{
			TV_Missions.Nodes.Clear();
			TV_AssignedUnits.Nodes.Clear();
			TV_UnassignedUnits.Nodes.Clear();
			if (_ServiceIndexer == null)
			{
				if (Client.CurrentSide != null && Client.CurrentSide.Missions.Count > 0)
				{
					SelectedMission = Client.CurrentSide.Missions[0];
				}
			}
			else if (!Client.CurrentSide.Missions.Contains(_ServiceIndexer))
			{
				if (Client.CurrentSide.Missions.Count <= 0)
				{
					SelectedMission = null;
				}
				else
				{
					SelectedMission = Client.CurrentSide.Missions[0];
				}
			}
			RefreshPresetFields();
			RefreshMissions();
			InterruptInterruptibleConsumer();
			AddInterruptibleConsumer();
			DeleteInterruptibleConsumer();
			DestroyInterruptibleConsumer();
			AddInterruptibleConsumer();
			DeleteInterruptibleConsumer();
			DestroyInterruptibleConsumer();
			CB_ScrubIfHuman.Visible = Client.CurrentGame.GameMode == Game._GameMode.ScenEdit;
			ToggleMissionPlannerTabControls();
			Button_FillEmptySlots_Strike.Visible = true;
