	public void RefreshMissions(bool bool_0 = false)
	{
		try
		{
			if (NewMission.CreatingNewMission)
			{
				return;
			}
			TV_Missions.Nodes.Clear();
			if (Client.CurrentSide == null)
			{
				return;
			}
			List<Mission> list = (from theM in Client.CurrentSide.GetMissionsTotal(Client.CurrentScenario)
				orderby theM.Name
				select theM).ToList();
			if (list.Count == 0)
			{
				SelectedMission = null;
			}
			List<Mission> list2 = list.Where((Mission x) => x.Category == Mission.MissionCategory.TaskPool).ToList();
			Dictionary<string, List<string>> dictionary = new Dictionary<string, List<string>>();
			foreach (Mission item in list2)
			{
				dictionary.Add(item.ObjectID, ((TaskPool)item).PackageList_IDs);
			}
			foreach (Mission item2 in list)
			{
				if ((!MissionFilter_Custom && (item2.CreationMode == MissionCreationType.Manually || item2.CreationMode == MissionCreationType.Unspecified)) || (!MissionFilter_Generated && (item2.CreationMode == MissionCreationType.Generated || item2.CreationMode == MissionCreationType.LandingPlanner)))
				{
					continue;
				}
				foreach (KeyValuePair<string, List<string>> item3 in dictionary)
				{
					foreach (string item4 in item3.Value)
					{
						if (Operators.CompareString(item4, item2.ObjectID, TextCompare: true) == 0)
						{
							item2.SetParentTaskPoolID(Client.CurrentSide, item3.Key);
							item2.Category = Mission.MissionCategory.Package;
						}
					}
				}
				if (item2.Category == Mission.MissionCategory.Package)
				{
					continue;
				}
				if (item2.Category == Mission.MissionCategory.Mission)
				{
					DarkTreeNode darkTreeNode = new DarkTreeNode(item2.Name + "  -" + item2.MissionClass.ToString() + "- " + item2.GetTargetCountString(Client.CurrentSide));
					TV_Missions.Nodes.Add(darkTreeNode);
					if (item2.IsActive)
					{
						if (item2.GetAdequateMissionWithNoTargets(Client.CurrentSide))
						{
							darkTreeNode.ForeColor = Color.Yellow;
						}
						else
						{
							darkTreeNode.ForeColor = Color.LightGreen;
						}
					}
					else
					{
						darkTreeNode.ForeColor = Color.IndianRed;
						darkTreeNode.Font = new Font(Font, FontStyle.Italic);
						DateTime? startTime = item2.StartTime;
						DateTime time = Client.CurrentScenario.Time;
						if ((startTime.HasValue ? new bool?(DateTime.Compare(startTime.GetValueOrDefault(), time) > 0) : null).GetValueOrDefault())
						{
							darkTreeNode.Text = "[D] " + item2.Name + " " + item2.GetTargetCountString(Client.CurrentSide);
						}
					}
					darkTreeNode.Tag = item2;
					continue;
				}
				DarkTreeNode darkTreeNode2 = new DarkTreeNode(item2.Name + " " + item2.GetTargetCountString(Client.CurrentSide));
				TV_Missions.Nodes.Add(darkTreeNode2);
				darkTreeNode2.Tag = item2;
				foreach (Mission item5 in ((TaskPool)item2).PackageList.OrderBy((Mission theP) => theP.Name))
				{
					DarkTreeNode darkTreeNode3 = new DarkTreeNode(item5.Name + "  -" + item5.MissionClass.ToString() + "- " + item5.GetTargetCountString(Client.CurrentSide));
					darkTreeNode2.Nodes.Add(darkTreeNode3);
					darkTreeNode3.Tag = item5;
					if (item5.GetAdequateMissionWithNoTargets(Client.CurrentSide))
					{
						darkTreeNode2.ForeColor = Color.Yellow;
					}
				}
			}
			if (bool_0 && SelectedMission != null)
			{
				foreach (DarkTreeNode item6 in TV_Missions.Nodes.ToList())
				{
					if (item6.Tag == SelectedMission && TV_Missions.SelectedNodes.Count == 1 && Operators.CompareString(((Mission)TV_Missions.SelectedNodes[0].Tag).ObjectID, SelectedMission.ObjectID, TextCompare: true) != 0)
					{
						TV_Missions.SelectNode(item6);
					}
				}
			}
			TV_Missions.Refresh();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200634", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

