				where TheAU != null
				select TheAU into theAU
				orderby theAU.Name
				select theAU into TheAu
				select (TheAu))
			{
				if (Information.IsNothing(item) || (item.IsWeapon && ((Weapon)item).Type == Weapon._WeaponType.Sonobuoy) || (item.IsShip && !parameterResolver) || (item.IsBoat && !parameterResolver) || (item.IsFacility && !objectResolver) || (item.IsVehicle && !objectResolver) || (item.IsAircraft && !_InstanceResolver) || (item.IsSatellite && !m_DispatcherResolver) || (!m_ExpressionResolver && item.AllowMultiMission) || (item.AssignedMissionOrPackage() != SelectedMission && (!m_ExpressionResolver || !item.AllowMultiMission || !item.AssignedMissionsQueue.ContainsKey(SelectedMission)) && (!Information.IsNothing(item.AssignedMissionOrPackage()) || item.AssignedTaskPool != SelectedMission)))
