			List<Aircraft> list6 = list2.Select((Aircraft theAC) => theAC).OrderBy((Aircraft theAirc) => theAirc.Navigator.GetFlight().Callsign, new NaturalSortComparer<string[]>()).ToList();
			List<ActiveUnit> list7 = list3.Select((ActiveUnit theAU) => theAU).OrderBy((ActiveUnit theAirc) => theAirc.UnitClass, new NaturalSortComparer<string[]>()).ToList();
			foreach (Aircraft item2 in list5)
