				string text5;
				if (activeUnit_.IsGroup)
				{
					Group group = (Group)activeUnit_;
					if (group.Type == Group.GroupType.AirGroup && group.Units.Values.Count > 0)
					{
						if (group.Units.Values.ElementAtOrDefault(0).IsAircraft)
