						text5 = (string.IsNullOrEmpty(group.Units.Values.ElementAtOrDefault(0).UnitClass) ? "" : (" " + group.Units.Values.ElementAtOrDefault(0).UnitClass));
						text3 = text3 + " (" + Conversions.ToString(group.Units.Count) + "x" + text5 + text4 + text + ")";
					}
				}
				if (activeUnit_.IsAircraft)
				{
					Aircraft aircraft2 = (Aircraft)activeUnit_;
					text4 = (Information.IsNothing(aircraft2.Loadout) ? "" : (" (" + aircraft2.Loadout.PushClass() + ")"));
				}
				else
				{
					text4 = "";
				}
				text5 = (string.IsNullOrEmpty(activeUnit_.UnitClass) ? "" : (" (" + Misc.ReadRequest(activeUnit_.UnitClass) + ")"));
				DarkTreeNode darkTreeNode_2 = new DarkTreeNode(text3 + text5 + text4);
