	private void FlushInterruptibleDefinition(object sender, EventArgs e)
	{
		try
		{
			if (TV_Missions.SelectedNodes.Count == 0)
			{
				return;
			}
			SelectedMission = (Mission)TV_Missions.SelectedNodes[0].Tag;
			if (Information.IsNothing(SelectedMission))
			{
				return;
			}
			if (SelectedMission.Category == Mission.MissionCategory.TaskPool)
			{
				DarkMessageBox.ShowWarning("Task Pools cannot be cloned", "Mission clone");
				return;
			}
			Mission selectedMission = SelectedMission;
			Scenario scenario_ = Client.CurrentScenario;
			Side side_ = Client.CurrentSide;
			Mission mission = selectedMission.StopValue(ref scenario_, ref side_);
			Client.CurrentSide = side_;
			Mission mission2 = mission;
			if (mission2.Category == Mission.MissionCategory.Package)
			{
				mission2.SetParentTaskPoolID(Client.CurrentSide, SelectedMission.GetParentTaskPoolID(Client.CurrentSide));
				foreach (Mission mission3 in Client.CurrentSide.Missions)
				{
					if (Operators.CompareString(mission3.ObjectID, mission2.GetParentTaskPoolID(Client.CurrentSide), TextCompare: true) == 0)
					{
						((TaskPool)mission3).PackageList.Add(mission2);
						((TaskPool)mission3).PackageList_IDs.Add(mission2.ObjectID);
					}
				}
			}
			SelectedMission.UnitsAssignedToMission = new ConcurrentDictionary<ActiveUnit, ActiveUnit>();
			if (mission2 != null)
			{
				Client.MissionEditorWindow.ReadInterruptibleDic();
				SelectedMission = mission2;
				RefreshMissions();
				MoveInterruptibleVal();
				RefreshAssignedUnits();
				RefreshUnassignedUnits();
				Client.MissionEditorWindow.DisableInterruptibleDic();
				TV_Missions.Select();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 09876583", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

