	private void CountInterruptibleVal(Scenario scenario_0, ActiveUnit activeUnit_0)
	{
		if (base.InvokeRequired)
		{
			Invoke((VB_0024AnonymousDelegate_0)delegate
			{
				CountInterruptibleVal(scenario_0, activeUnit_0);
			});
		}
		else
		{
			if (scenario_0 != Client.CurrentScenario)
			{
				return;
			}
			DarkTreeNode Local_NodeToRemove = null;
			foreach (DarkTreeNode item in InterpreterObjectListener.PrintInterruptibleTask(TV_AssignedUnits))
			{
				if (item.Tag == activeUnit_0)
				{
					Local_NodeToRemove = item;
					break;
				}
			}
			if (Local_NodeToRemove != null)
			{
				TV_AssignedUnits.Invoke((VB_0024AnonymousDelegate_0)delegate
				{
					Local_NodeToRemove.Remove();
				});
			}
			Local_NodeToRemove = null;
			foreach (DarkTreeNode item2 in InterpreterObjectListener.PrintInterruptibleTask(TV_UnassignedUnits))
			{
				if (item2.Tag == activeUnit_0)
				{
					Local_NodeToRemove = item2;
					break;
				}
			}
			if (Local_NodeToRemove != null)
			{
				TV_UnassignedUnits.Invoke((VB_0024AnonymousDelegate_0)delegate
				{
					Local_NodeToRemove.Remove();
				});
			}
			List<Mission> list = new List<Mission>();
			List<Mission> list2 = new List<Mission>();
			if (Client.CurrentGame.GameMode == Game._GameMode.ScenEdit)
			{
				Side[] sides_ReadOnly = Client.CurrentScenario.Sides_ReadOnly;
				Side[] array = sides_ReadOnly;
				foreach (Side side in array)
				{
					list.AddRange(side.Missions.ToList());
				}
			}
			else
			{
				list = Client.CurrentSide.Missions.ToList();
			}
			foreach (Mission item3 in list)
			{
				switch (item3.MissionClass)
				{
				case Mission._MissionClass.Cargo:
				{
					CargoMission cargoMission = (CargoMission)item3;
					if (cargoMission.DestinationUnit == activeUnit_0)
					{
						cargoMission.DestinationUnit = null;
						list2.Add(item3);
					}
					break;
				}
				case Mission._MissionClass.Ferry:
				{
					FerryMission ferryMission = (FerryMission)item3;
					if (ferryMission.GetNominalDestinationHost(Client.CurrentScenario) == activeUnit_0)
					{
						ferryMission.SetNominalDestinationHost(Client.CurrentScenario, null);
						list2.Add(item3);
					}
					break;
				}
				}
			}
			if (Client.CurrentGame.GameMode == Game._GameMode.ScenEdit && list2.Count > 0)
			{
				string text = "Mission destination unit '" + activeUnit_0.Name + "' has been removed or destroyed. The following missions can no longer execute properly: " + list2[0].Name;
				int num = list2.Count - 1;
				for (int i = 1; i <= num; i++)
				{
					text = text + ", " + list2[i].Name;
				}
				DarkMessageBox.ShowWarning(text, string.Empty);
			}
		}
	}

