	private void CallInterruptibleVal(object sender, EventArgs e)
	{
		switch (Combo_Strike_MinimumContactStanceToTrigger.SelectedIndex)
		{
		case 0:
			((Strike)SelectedMission).MinimumContactStanceToTrigger = Misc.PostureStance.Unknown;
			break;
		case 1:
			((Strike)SelectedMission).MinimumContactStanceToTrigger = Misc.PostureStance.Unfriendly;
			break;
		case 2:
			((Strike)SelectedMission).MinimumContactStanceToTrigger = Misc.PostureStance.Hostile;
			break;
		}
	}

	private void LogoutInterruptibleVal(object sender, EventArgs e)
	{
		if (m_WrapperResolver)
		{
			ViewInterruptibleVal(TV_AssignedUnits);
			SelectedMission.TimeSincePlayerNotification = 0;
		}
		else
		{
			ViewInterruptibleVal(TV_UnassignedUnits);
		}
	}

	private void ViewInterruptibleVal(DarkTreeView darkTreeView_0)
	{
		List<Aircraft> list = new List<Aircraft>();
		int num = 0;
		ActiveUnit activeUnit = null;
		bool flag = false;
		Aircraft aircraft = null;
		List<Mission.EmptyAircraftSlot> list2 = new List<Mission.EmptyAircraftSlot>();
		Mission.EmptyAircraftSlot emptyAircraftSlot = null;
		foreach (DarkTreeNode selectedNode in darkTreeView_0.SelectedNodes)
		{
			if ((object)selectedNode.Tag.GetType() == typeof(Aircraft))
			{
				aircraft = (Aircraft)selectedNode.Tag;
				if (!aircraft.IsOperating())
				{
					if (num == 0)
					{
						num = aircraft.DBID;
						activeUnit = aircraft.AirOps.CurrentHostUnit;
						list.Add(aircraft);
					}
					else if (num == aircraft.DBID && aircraft.AirOps.CurrentHostUnit == activeUnit)
					{
						list.Add(aircraft);
					}
					else
					{
						flag = true;
					}
				}
			}
			else if ((object)selectedNode.Tag.GetType() == typeof(Mission.EmptyAircraftSlot))
			{
				emptyAircraftSlot = (Mission.EmptyAircraftSlot)selectedNode.Tag;
				if (num == 0)
				{
					num = emptyAircraftSlot.ReferenceUnit_DBID;
					activeUnit = emptyAircraftSlot.GetCurrentHostUnit(Client.CurrentScenario);
					list2.Add(emptyAircraftSlot);
				}
				else if (num == emptyAircraftSlot.ReferenceUnit_DBID && emptyAircraftSlot.GetCurrentHostUnit(Client.CurrentScenario) == activeUnit)
				{
					list2.Add(emptyAircraftSlot);
				}
				else
				{
					flag = true;
				}
			}
		}
		if (list.Count == 0 && list2.Count == 0)
		{
			DarkMessageBox.ShowWarning("你没有选择任何飞机，或者你选择的所有飞机都在空中。", "选择无效！");
			return;
		}
		if (Client.CurrentGame.GameMode != Game._GameMode.ScenEdit)
		{
			List<Aircraft> list3 = new List<Aircraft>();
			foreach (Aircraft item in list)
			{
				string string_ = null;
				if (item.IsAvailableForOps(ref string_) == Aircraft_AirOps.AirOpsAvailabilityStatus.IsUnderMaintenance)
				{
					list3.Add(item);
				}
			}
			if (list3.Count > 0)
			{
				DarkMessageBox.ShowWarning(Conversions.ToString(list3.Count) + "架所选飞机无法进行操作，将不进行出动准备。", "选择了不可用的飞机！");
				foreach (Aircraft item2 in list3)
				{
					list.Remove(item2);
				}
			}
		}
		if (list.Count != 0 || list2.Count != 0)
		{
			if (flag)
			{
				DarkMessageBox.ShowWarning("你选择了多个类型的飞机或多个基地。你只能就绪所选的第一种类型的飞机（" + Misc.ReadRequest(list[0].UnitClass) + "）在第一个选定的基地（" + list[0].AirOps.CurrentHostUnit.Name + ").", "多项选择");
			}
			ItemExporter.ConnectInterruptibleTemplate.ReadyAircraft.SelectedAircraft = list;
			ItemExporter.ConnectInterruptibleTemplate.ReadyAircraft.SelectedEmptySlot = list2;
			ItemExporter.ConnectInterruptibleTemplate.ReadyAircraft.Show();
		}
	}

