	private void ChangeInterruptibleVal(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Strike)
		{
			return;
		}
		bool flag = false;
		bool flag2 = false;
		string text = "";
		foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
		{
			if (selectedUnit.GetUnitSide() == Client.CurrentSide || Module_Side.IsAlliedWithThisSide(Client.CurrentSide, selectedUnit.GetUnitSide()))
			{
				continue;
			}
			if (selectedUnit.IsGroup)
			{
				foreach (ActiveUnit value in ((Group)selectedUnit).Units.Values)
				{
					if (value.GetIsAutoDetectable(Client.CurrentSide))
					{
						flag2 = true;
						text = text + " " + value.Name;
					}
					((Strike)SelectedMission).SpecificTargets.Add(value);
					flag = true;
				}
				if (SelectedMission.IsActive && Client.CurrentSide.GetConsidersThisSideToBe(selectedUnit.GetUnitSide()) != Misc.PostureStance.Hostile)
				{
					Client.CurrentSide.SetConsidersThisSideToBe(selectedUnit.GetUnitSide(), Misc.PostureStance.Hostile);
				}
				continue;
			}
			if (selectedUnit.IsActiveUnit)
			{
				if (((ActiveUnit)selectedUnit).GetIsAutoDetectable(Client.CurrentSide))
				{
					flag2 = true;
					text = text + " " + selectedUnit.Name;
				}
				((Strike)SelectedMission).SpecificTargets.Add(selectedUnit);
				flag = true;
				if (SelectedMission.IsActive && Client.CurrentSide.GetConsidersThisSideToBe(selectedUnit.GetUnitSide()) != Misc.PostureStance.Hostile)
				{
					Client.CurrentSide.SetConsidersThisSideToBe(selectedUnit.GetUnitSide(), Misc.PostureStance.Hostile);
				}
				continue;
			}
			Contact contact = (Contact)selectedUnit;
			if (!Information.IsNothing(contact.ActualUnit) && Client.CurrentSide.BaseContacts.ContainsKey(contact.ActualUnit.ObjectID))
			{
				foreach (ActiveUnit value2 in ((Group)contact.ActualUnit).Units.Values)
				{
					if (value2.GetIsAutoDetectable(Client.CurrentSide))
					{
						flag2 = true;
						text = text + " " + value2.Name;
					}
					((Strike)SelectedMission).SpecificTargets.Add(value2);
				}
			}
			else
			{
				if (Client.CurrentSide.BaseContacts.ContainsKey(contact.ActualUnit.ObjectID))
				{
					continue;
				}
				if (contact.ActualUnit != null && contact.ActualUnit.GetIsAutoDetectable(Client.CurrentSide))
				{
					flag2 = true;
					text = text + " " + contact.Name;
				}
				((Strike)SelectedMission).SpecificTargets.Add(contact);
				flag = true;
			}
			if (SelectedMission.IsActive && contact.GetStance(Client.CurrentSide) != Misc.PostureStance.Hostile)
			{
				contact.SetStance(Client.CurrentSide, bool_0: false, Misc.PostureStance.Hostile);
			}
		}
		if (flag2)
		{
			DarkMessageBox.ShowWarning("Unit(s) " + text + " are auntodetectable, some weapons might need a detected emission to engage", "Auto detectable found");
		}
		if (flag)
		{
			DarkTreeNode darkTreeNode = TV_Missions.SelectedNodes.FirstOrDefault();
			RefreshMissions();
			if (TV_Missions.SelectedNodes != null && darkTreeNode != null)
			{
				TV_Missions.SelectNode(darkTreeNode);
			}
		}
		InitInterruptibleVal(bool_0: true);
		SelectedMission.TimeSincePlayerNotification = 0;
		Client.MustRefreshMainForm = true;
	}

	private void InitInterruptibleVal(bool bool_0 = false)
	{
		TabPageTargets.Name = "Targets";
		float num = 0f;
		observerResolver = new List<KeyValuePair<Module_Unit.Unit, Mission>>();
		ListBox_Targets.RelatedInfos = new List<KeyValuePair<string, string>>();
		foreach (Mission mission in Client.CurrentSide.Missions)
		{
			if ((object)mission.GetType() != typeof(Strike) || Operators.CompareString(mission.Name, SelectedMission.Name, TextCompare: true) == 0)
			{
				continue;
			}
			foreach (Module_Unit.Unit specificTarget in ((Strike)mission).SpecificTargets)
			{
				observerResolver.Add(new KeyValuePair<Module_Unit.Unit, Mission>(specificTarget, mission));
				ListBox_Targets.RelatedInfos.Add(new KeyValuePair<string, string>(specificTarget.ToString(), mission.Name));
			}
		}
		ListBox_Targets.Items.Clear();
		if (bool_0)
		{
			foreach (Module_Unit.Unit Local_theU2 in ((Strike)SelectedMission).SpecificTargets.OrderBy((Module_Unit.Unit theUnit) => theUnit.Name))
			{
				DarkListItem darkListItem = new DarkListItem(Local_theU2.Name);
				darkListItem.Tag = Local_theU2;
				int num2 = observerResolver.Where((KeyValuePair<Module_Unit.Unit, Mission> x) => Operators.CompareString(x.Key.ObjectID, Local_theU2.ObjectID, TextCompare: true) == 0).Count();
				if (num2 == 1)
				{
					darkListItem.Text = "[ " + num2 + " other Strike Mission  ]  " + darkListItem.Text;
				}
				else if (num2 > 1)
				{
					darkListItem.Text = "[ " + num2 + " other Strike Missions  ]  " + darkListItem.Text;
				}
				if (Local_theU2.IsActiveUnit && ((ActiveUnit)Local_theU2).GetParentGroup() != null && ((ActiveUnit)Local_theU2).GetParentGroup().Name.Count() > 0)
				{
					darkListItem.Text = darkListItem.Text + " -> " + ((ActiveUnit)Local_theU2).GetParentGroup().Name;
				}
				ListBox_Targets.Items.Add(darkListItem);
			}
		}
		else
		{
			foreach (Module_Unit.Unit Local_theU in ((Strike)SelectedMission).SpecificTargets)
			{
				DarkListItem darkListItem2 = new DarkListItem(Local_theU.Name);
				darkListItem2.Tag = Local_theU;
				int num3 = observerResolver.Where((KeyValuePair<Module_Unit.Unit, Mission> x) => Operators.CompareString(x.Key.ObjectID, Local_theU.ObjectID, TextCompare: true) == 0).Count();
				if (num3 == 1)
				{
					darkListItem2.Text = "[ " + num3 + " other Strike Mission  ]  " + darkListItem2.Text;
				}
				else if (num3 > 1)
				{
					darkListItem2.Text = "[ " + num3 + " other Strike Missions  ]  " + darkListItem2.Text;
				}
				if (Local_theU.IsActiveUnit && ((ActiveUnit)Local_theU).GetParentGroup() != null && ((ActiveUnit)Local_theU).GetParentGroup().Name.Count() > 0)
				{
					darkListItem2.Text = darkListItem2.Text + " -> " + ((ActiveUnit)Local_theU).GetParentGroup().Name;
				}
				ListBox_Targets.Items.Add(darkListItem2);
			}
		}
		num = ListBox_Targets.Items.Count;
		GroupBoxTargets.Text = "目标列表 (" + num + ")";
		string text = "";
		foreach (DarkListItem item in ListBox_Targets.Items)
		{
			if (Operators.CompareString(text, "", TextCompare: true) != 0)
			{
				text = Environment.NewLine ?? "";
			}
			text += item.Text;
		}
		if (num == 1f)
		{
			TabPageTargets.Text = "一个目标";
		}
		else if (num == 0f)
		{
			TabPageTargets.Text = "没有目标";
		}
		else
		{
			TabPageTargets.Text = num + " 个目标";
		}
	}

