	private void CheckInterruptibleVal(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission) || ListBox_Targets.SelectedIndices.Count == 0 || SelectedMission.MissionClass != Mission._MissionClass.Strike)
		{
			return;
		}
		List<DarkListItem> list = new List<DarkListItem>();
