	private void RemoveInterruptibleVal(object sender, KeyEventArgs e)
	{
		if ((e.KeyCode == Keys.Escape && base.Visible) || (e.KeyCode == Keys.F11 && base.Visible))
		{
			RegisterInterruptibleDefinition();
			StartInterruptibleVal();
			DefineInterruptibleVal();
			PublishInterruptibleVal();
			RestartInterruptibleIssuer();
			RegisterInterruptibleVal();
			CountInterruptibleWrapper();
			DeleteInterruptibleWrapper();
			PatchInterruptibleWrapper();
			LogoutInterruptibleWrapper();
			LoginInterruptibleWrapper();
			NewInterruptibleWrapper();
			SetupInterruptibleWrapper();
			SearchInterruptibleWrapper();
			VisitInterruptibleWrapper();
			AwakeInterruptibleVal();
			QueryInterruptibleVal();
			ResetInterruptibleVal();
			CancelInterruptibleIssuer();
			MapInterruptibleVal();
			SortInterruptibleVal();
			FlushInterruptibleVal();
			ForgotInterruptibleVal();
			CollectInterruptibleVal();
			OrderInterruptibleVal();
			PushInterruptibleIssuer();
			SetupInterruptibleIssuer();
			IncludeInterruptibleIssuer();
			EnableInterruptibleIssuer();
			ResetInterruptibleWrapper();
			ForgotInterruptibleWrapper();
			AssetInterruptibleIssuer();
			SortInterruptibleClient();
			PrintInterruptibleClient();
			CloneInterruptibleDic();
			OrderInterruptibleClient();
			Close();
		}
		else if (e.KeyCode == Keys.Return && base.Visible)
		{
			RegisterInterruptibleDefinition();
			StartInterruptibleVal();
			DefineInterruptibleVal();
			RegisterInterruptibleVal();
			CountInterruptibleWrapper();
			DeleteInterruptibleWrapper();
			PatchInterruptibleWrapper();
			LogoutInterruptibleWrapper();
			LoginInterruptibleWrapper();
			NewInterruptibleWrapper();
			SetupInterruptibleWrapper();
			SearchInterruptibleWrapper();
			VisitInterruptibleWrapper();
			AwakeInterruptibleVal();
			QueryInterruptibleVal();
			ResetInterruptibleVal();
			MapInterruptibleVal();
			SortInterruptibleVal();
			FlushInterruptibleVal();
			ForgotInterruptibleVal();
			CollectInterruptibleVal();
			OrderInterruptibleVal();
			PushInterruptibleIssuer();
			SetupInterruptibleIssuer();
			IncludeInterruptibleIssuer();
			EnableInterruptibleIssuer();
			ResetInterruptibleWrapper();
			ForgotInterruptibleWrapper();
			AssetInterruptibleIssuer();
			ItemExporter.ConnectInterruptibleTemplate.TankerPlanner.Close();
			SortInterruptibleClient();
			PrintInterruptibleClient();
			CloneInterruptibleDic();
			OrderInterruptibleClient();
		}
		else if (!systemIndexer)
		{
			if (e.KeyCode == Keys.F1 || e.KeyCode == Keys.F2 || e.KeyCode == Keys.F3 || e.KeyCode == Keys.F4 || e.KeyCode == Keys.F5 || e.KeyCode == Keys.F6 || e.KeyCode == Keys.F7 || e.KeyCode == Keys.F8 || e.KeyCode == Keys.F9 || e.KeyCode == Keys.F10 || e.KeyCode == Keys.F11 || e.KeyCode == Keys.F12)
			{
				ItemExporter.ConnectInterruptibleTemplate.MainForm.Main_KeyDown(RuntimeHelpers.GetObjectValue(sender), e);
			}
			if (e.KeyCode == Keys.Space)
			{
				ItemExporter.ConnectInterruptibleTemplate.MainForm.Main_KeyDown(RuntimeHelpers.GetObjectValue(sender), e);
			}
		}
	}

