	private void StartInterruptibleVal()
	{
		try
		{
			if (m_IdentifierIndexer)
			{
				m_IdentifierIndexer = false;
				if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Patrol)
				{
					return;
				}
				if (!string.IsNullOrEmpty(TB_PatrolTransitAltitude_Aircraft.Text) && Versioned.IsNumeric(TB_PatrolTransitAltitude_Aircraft.Text))
				{
					if (Conversions.ToInteger(TB_PatrolTransitAltitude_Aircraft.Text) <= 0)
					{
						((Patrol)SelectedMission).TransitAltitude_Aircraft = null;
						TB_PatrolTransitAltitude_Aircraft.Text = "";
						CheckBox_PatrolTransitTerrainFollowing_Aircraft.Enabled = false;
						return;
					}
					if (SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
					{
						((Patrol)SelectedMission).TransitAltitude_Aircraft = Conversions.ToSingle(TB_PatrolTransitAltitude_Aircraft.Text) * 0.3048f;
					}
					else
					{
						((Patrol)SelectedMission).TransitAltitude_Aircraft = Conversions.ToSingle(TB_PatrolTransitAltitude_Aircraft.Text);
					}
					CheckBox_PatrolTransitTerrainFollowing_Aircraft.Enabled = true;
				}
				else
				{
					((Patrol)SelectedMission).TransitAltitude_Aircraft = null;
					TB_PatrolTransitAltitude_Aircraft.Text = "";
					CheckBox_PatrolTransitTerrainFollowing_Aircraft.Enabled = false;
				}
			}
			else
			{
				m_IdentifierIndexer = false;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			m_IdentifierIndexer = false;
			ProjectData.ClearProjectError();
		}
	}

