				if (!string.IsNullOrEmpty(TB_PatrolTransitDepth_Submarine.Text) && Versioned.IsNumeric(TB_PatrolTransitDepth_Submarine.Text))
				{
					float num = Conversions.ToSingle(TB_PatrolTransitDepth_Submarine.Text);
					if (num > 0f)
					{
						num *= -1f;
						TB_PatrolTransitDepth_Submarine.Text = Conversions.ToString(num);
