	private void UpdateInterruptibleWrapper(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission))
		{
			return;
		}
		if (SelectedMission.MissionClass == Mission._MissionClass.Escort)
		{
			if (!Information.IsNothing(SelectedMission))
			{
				EscortMission escortMission = (EscortMission)SelectedMission;
				ActiveUnit.Throttle throttle = (ActiveUnit.Throttle)(Combo_EscortTransitThrottle_Aircraft.SelectedIndex + 1);
				if ((int)throttle <= 4)
				{
					escortMission.TransitThrottle = throttle;
				}
				else
				{
					escortMission.TransitThrottle = null;
				}
			}
		}
		else if (SelectedMission.MissionClass == Mission._MissionClass.Strike && !Information.IsNothing(SelectedMission))
		{
			Strike strike = (Strike)SelectedMission;
			ActiveUnit.Throttle throttle2 = (ActiveUnit.Throttle)(Combo_EscortTransitThrottle_Aircraft.SelectedIndex + 1);
			if ((int)throttle2 <= 4)
			{
				strike.Escort_TransitThrottle = throttle2;
			}
			else
			{
				strike.Escort_TransitThrottle = null;
			}
		}
	}

