	private void VisitInterruptibleWrapper()
	{
		try
		{
			if (_MapperIndexer)
			{
				_MapperIndexer = false;
				if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Strike || string.IsNullOrEmpty(TB_EscortResponseRadius_Shooter.Text))
				{
					return;
				}
				if (Versioned.IsNumeric(TB_EscortResponseRadius_Shooter.Text))
				{
					if (Conversions.ToInteger(TB_EscortResponseRadius_Shooter.Text) < 0)
					{
						((Strike)SelectedMission).Escort_ResponseRadius = 0;
					}
					else
					{
						((Strike)SelectedMission).Escort_ResponseRadius = Conversions.ToInteger(TB_EscortResponseRadius_Shooter.Text);
					}
				}
				else
				{
					((Strike)SelectedMission).Escort_ResponseRadius = 0;
				}
			}
			else
			{
				_MapperIndexer = false;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			_MapperIndexer = false;
			ProjectData.ClearProjectError();
		}
	}

