		{
			SelectedMission.Doctrine.SetUseReplenishment(Client.CurrentScenario, bool_0: false, bool_1: false, bool_2: false, bool_3: false, Doctrine._UseUnderwayRefuelAndReplenishment.Always_ExceptTankersRefuellingTankers);
		}
		else if (CB_TankerUsage.SelectedIndex == 2)
		{
			SelectedMission.Doctrine.SetUseReplenishment(Client.CurrentScenario, bool_0: false, bool_1: false, bool_2: false, bool_3: false, Doctrine._UseUnderwayRefuelAndReplenishment.Never);
		}
		else
		{
			SelectedMission.Doctrine.SetUseReplenishment(Client.CurrentScenario, bool_0: false, bool_1: false, bool_2: false, bool_3: false, null);
		}
		SelectedMission.TimeSincePlayerNotification = 0;
	}

