	private void LoginInterruptibleIssuer()
	{
		try
		{
			if ((Operators.CompareString(clientResolver, DateTimePicker_TakeOffDate.Text + DateTimePicker_TakeOffTime.Text, TextCompare: true) != 0) | (Operators.CompareString(m_IssuerResolver, DateTimePicker_TimeOnTargetDate.Text + DateTimePicker_TimeOnTargetTime.Text, TextCompare: true) != 0))
			{
				clientResolver = DateTimePicker_TakeOffDate.Text + DateTimePicker_TakeOffTime.Text;
				m_IssuerResolver = DateTimePicker_TimeOnTargetDate.Text + DateTimePicker_TimeOnTargetTime.Text;
				switch (SelectedMission.MissionClass)
				{
				case Mission._MissionClass.Strike:
					LoginInterruptibleClient(Txt_FlightSize_Strike);
					break;
				case Mission._MissionClass.Patrol:
					LoginInterruptibleClient(Txt_FlightSize_Patrol);
					break;
				case Mission._MissionClass.Support:
					LoginInterruptibleClient(Txt_FlightSize_Support);
					break;
				case Mission._MissionClass.Ferry:
					LoginInterruptibleClient(Txt_FlightgSize_Ferry);
					break;
				case Mission._MissionClass.Mining:
					LoginInterruptibleClient(Txt_FlightgSize_Mining);
					break;
				case Mission._MissionClass.MineClearing:
					LoginInterruptibleClient(Txt_FlightgSize_MinineClearing);
					break;
				}
				RefreshAssignedUnits();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 23453209804011999", "");
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void GetInterruptibleIssuer(DarkMaskedTextBox darkMaskedTextBox_0, DarkMaskedTextBox darkMaskedTextBox_1, TimeSpan timeSpan_0)
	{
		darkMaskedTextBox_0.Mask = "0000-00-00";
		darkMaskedTextBox_1.Mask = "00:00:00";
		DateTime dateTime_ = Client.CurrentScenario.Time.Add(timeSpan_0);
		string string_ = "";
		string string_2 = "";
		GameGeneral.PaddedTimeString(ref dateTime_, ref string_);
		GameGeneral.PaddedDateString(ref dateTime_, ref string_2, bool_1: false);
		darkMaskedTextBox_1.Text = string_;
		darkMaskedTextBox_0.Text = string_2;
	}

	private bool WriteInterruptibleIssuer(DarkMaskedTextBox darkMaskedTextBox_0, DarkMaskedTextBox darkMaskedTextBox_1, ref DateTime dateTime_0)
	{
		DateTime dateTime_ = default(DateTime);
		int num = RuleTokenizer.ChangeServer(darkMaskedTextBox_0.Text, darkMaskedTextBox_1.Text, ref dateTime_);
		if (num == 0)
		{
			dateTime_0 = dateTime_;
			return true;
		}
		Interaction.Beep();
		if (num == 1)
		{
			darkMaskedTextBox_0.Select();
			DarkMessageBox.ShowWarning("Date must be in YYYY-MM-DD format", "Invalid Date");
		}
		else
		{
			darkMaskedTextBox_1.Select();
			DarkMessageBox.ShowWarning("Time must be in hh:mm:ss format", "Invalid Time");
		}
		dateTime_0 = DateTime.MinValue;
		return false;
	}

