	private void SetupInterruptibleIssuer()
	{
		try
		{
			DateTime dateTime_ = default(DateTime);
			if (m_ProducerIndexer && !Information.IsNothing(SelectedMission) && WriteInterruptibleIssuer(DateTimePicker_DeactivationDate, DateTimePicker_DeactivationTime, ref dateTime_))
			{
				SelectedMission.EndTime_Set(dateTime_, Client.CurrentScenario);
				bool? flag;
				if (Information.IsNothing(SelectedMission.StartTime))
				{
					flag = true;
				}
				else
				{
					DateTime? startTime = SelectedMission.StartTime;
					DateTime time = Client.CurrentScenario.Time;
					flag = (startTime.HasValue ? new bool?(DateTime.Compare(startTime.GetValueOrDefault(), time) < 0) : null);
				}
				bool? flag2 = flag;
				if (flag2.GetValueOrDefault(true))
				{
					if (!Information.IsNothing(SelectedMission.EndTime))
					{
						DateTime? endTime = SelectedMission.EndTime;
						DateTime time2 = Client.CurrentScenario.Time;
						if (!(endTime.HasValue ? new bool?(DateTime.Compare(endTime.GetValueOrDefault(), time2) > 0) : null).GetValueOrDefault())
						{
							goto IL_019a;
						}
					}
					if (flag2.HasValue)
					{
						SelectedMission.SetStatus(Client.CurrentScenario, Mission.MissionStatus.Active);
						goto IL_0177;
					}
				}
				goto IL_019a;
			}
			goto IL_0190;
			IL_019a:
			SelectedMission.SetStatus(Client.CurrentScenario, Mission.MissionStatus.Inactive);
			goto IL_0177;
			IL_0177:
			m_ProducerIndexer = false;
			RefreshMissions(bool_0: true);
			MoveInterruptibleVal();
			goto IL_0190;
			IL_0190:
			m_ProducerIndexer = false;
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			m_ProducerIndexer = false;
			ProjectData.ClearProjectError();
		}
	}

