	private void RestartInterruptibleIssuer()
	{
		try
		{
			if (algoIndexer)
			{
				algoIndexer = false;
				if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Patrol)
				{
					return;
				}
				if (string.IsNullOrEmpty(TB_PatrolAttackDistance_Aircraft.Text))
				{
					((Patrol)SelectedMission).AttackDistance_Aircraft = null;
					TB_PatrolAttackDistance_Aircraft.Text = "";
				}
				else if (Versioned.IsNumeric(TB_PatrolAttackDistance_Aircraft.Text))
				{
					if (Conversions.ToInteger(TB_PatrolAttackDistance_Aircraft.Text) <= 0)
					{
						((Patrol)SelectedMission).AttackDistance_Aircraft = null;
						TB_PatrolAttackDistance_Aircraft.Text = "";
					}
					else
					{
						((Patrol)SelectedMission).AttackDistance_Aircraft = Conversions.ToSingle(TB_PatrolAttackDistance_Aircraft.Text);
					}
				}
				else
				{
					((Patrol)SelectedMission).AttackDistance_Aircraft = null;
					TB_PatrolAttackDistance_Aircraft.Text = "";
				}
			}
			else
			{
				algoIndexer = false;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			algoIndexer = false;
			ProjectData.ClearProjectError();
		}
	}

