			m_AnnotationIndexer = false;
			if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Patrol)
			{
				return;
			}
			if (string.IsNullOrEmpty(TB_PatrolAttackDistance_Ship.Text))
			{
				((Patrol)SelectedMission).AttackDistance_Ship = null;
				TB_PatrolAttackDistance_Ship.Text = "";
			}
