	private void AssetInterruptibleIssuer()
	{
		try
		{
			if (_MerchantResolver)
			{
				_MerchantResolver = false;
				if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Support)
				{
					if (string.IsNullOrEmpty(TB_NumberOfReceiversA2AR.Text))
					{
						((SupportMission)SelectedMission).A2AR_MaxNumberOfReceiversPerTanker = 0;
						TB_NumberOfReceiversA2AR.Text = "0";
					}
					else if (Versioned.IsNumeric(TB_NumberOfReceiversA2AR.Text))
					{
						((SupportMission)SelectedMission).A2AR_MaxNumberOfReceiversPerTanker = Conversions.ToInteger(TB_NumberOfReceiversA2AR.Text);
					}
					else
					{
						((SupportMission)SelectedMission).A2AR_MaxNumberOfReceiversPerTanker = 0;
						TB_NumberOfReceiversA2AR.Text = "0";
					}
				}
			}
			else
			{
				_MerchantResolver = false;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			_MerchantResolver = false;
			ProjectData.ClearProjectError();
		}
	}

