	private void LoginInterruptibleClient(DarkUITextBox darkUITextBox_0)
	{
		int num = int.Parse(darkUITextBox_0.Text);
		List<ActiveUnit> list = new List<ActiveUnit>();
		try
		{
			if (Information.IsNothing(SelectedMission))
			{
				DarkMessageBox.ShowWarning("Select a Mission before create a Flightplan", "No mission selected");
				return;
			}
			if (Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario).Count == 0)
			{
				DarkMessageBox.ShowWarning("No units are assigned to this mission, flight creation will be interrupted", "No units are assigned to this mission");
				return;
			}
			if (!Versioned.IsNumeric(darkUITextBox_0.Text))
			{
				DarkMessageBox.ShowWarning("Define a valid number of aircraft before creating flightplans", "Incorrect aircraft number");
				return;
			}
			if (SelectedMission.FlightSize < 6)
			{
				SelectedMission.FlightSize = int.Parse(darkUITextBox_0.Text);
			}
			else
			{
				SelectedMission.FlightSize = 6;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 09876540", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
		foreach (ActiveUnit item in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario))
		{
			ActiveUnit_Navigator navigator = item.Navigator;
			Waypoint[] gparam_ = navigator.PlottedCourse;
			ArrayExtensions.Clear(ref gparam_);
			navigator.PlottedCourse = gparam_;
		}
		while (SelectedMission.FlightList.Count > 0)
		{
			try
			{
				Mission.Flight flight = SelectedMission.FlightList.Last();
				list = (from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
					where !Information.IsNothing(x.Navigator.GetFlight())
					select x).ToList();
				foreach (ActiveUnit Local_theUnit in list)
				{
					if (Local_theUnit.Navigator.GetFlight() != null && Operators.CompareString(Local_theUnit.Navigator.GetFlight().Callsign, flight.Callsign, TextCompare: true) == 0)
					{
						(from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
							where Operators.CompareString(x.ObjectID, Local_theUnit.ObjectID, TextCompare: true) == 0
							select x).FirstOrDefault().Navigator.ClearFlight();
					}
				}
				SelectedMission.FlightList.Remove(flight);
			}
			catch (Exception ex9)
			{
				ProjectData.SetProjectError(ex9);
				Exception exception_9 = ex9;
				exception_9?.Data.Add("Error at 09876541", exception_9.Message);
				GameGeneral.WriteExceptionsToLog(ref exception_9);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
			}
		}
		int num2 = int.Parse(darkUITextBox_0.Text);
		try
		{
			Mission selectedMission = SelectedMission;
			Scenario scenario_ = Client.CurrentScenario;
			Side side_ = Client.CurrentSide;
			PopInterruptibleDic(selectedMission, ref scenario_, ref side_, num2);
			Client.CurrentSide = side_;
		}
		catch (Exception ex10)
		{
			ProjectData.SetProjectError(ex10);
			Exception exception_10 = ex10;
			exception_10?.Data.Add("Error at 09876542", exception_10.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_10);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
		float num3 = 0f;
		string text = "";
		foreach (KeyValuePair<ActiveUnit, ActiveUnit> item2 in SelectedMission.UnitsAssignedToMission)
		{
			try
			{
				if (!item2.Key.IsAircraft)
				{
					continue;
				}
				Aircraft aircraft = (Aircraft)item2.Key;
				if (!aircraft.AirOps.ReflectProxy())
				{
					text = text + " " + aircraft.Name + " " + aircraft.AirOps.WeatherString;
				}
				if (!aircraft.AirOps.InterruptProxy(SelectedMission.SecondaryAirBase))
				{
					text = text + " " + aircraft.Name + " " + aircraft.AirOps.WeatherString;
				}
				if (SelectedMission.StartTime.HasValue)
				{
					if (aircraft.AirOps.ConditionTimer > (float)(Misc.LoginValue(SelectedMission.StartTime.Value) - Misc.LoginValue(Client.CurrentScenario.Time)) && aircraft.AirOps.ConditionTimer > num3)
					{
						num3 = aircraft.AirOps.ConditionTimer;
					}
				}
				else if (aircraft.AirOps.ConditionTimer > num3)
				{
					num3 = aircraft.AirOps.ConditionTimer;
				}
			}
			catch (Exception ex11)
			{
				ProjectData.SetProjectError(ex11);
				Exception exception_11 = ex11;
				exception_11?.Data.Add("Error at 09876543", exception_11.Message);
				GameGeneral.WriteExceptionsToLog(ref exception_11);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
			}
		}
		try
		{
			if (Operators.CompareString(text, "", TextCompare: true) != 0)
			{
				DarkMessageBox.ShowWarning(text, "Weather Limitation");
			}
			if (num3 > 0f)
			{
				DateTime dateTime = Client.CurrentScenario.Time.AddSeconds(num3);
				DarkMessageBox.ShowWarning("One Or more aircraft will be ready on " + Conversions.ToString(dateTime) + " check flightplan", "AC readying");
			}
		}
		catch (Exception ex12)
		{
			ProjectData.SetProjectError(ex12);
			Exception exception_12 = ex12;
			exception_12?.Data.Add("Error at 09876544", exception_12.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_12);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
		Client.MustRefreshMainForm = true;
		int num4 = 8;
		try
		{
