	public static bool Check_ACs_Crash(List<ActiveUnit> list_0)
	{
		if (Client.FlightPlanEditorWindow.SelectedFlight != null)
		{
			string text = "";
			foreach (ActiveUnit item in list_0)
			{
				float num = 0f;
				bool flag = false;
				int num2 = item.Navigator.GetFlight().FlightPlan.Count() - 1;
				for (int i = 1; i <= num2; i++)
				{
					if (item.Navigator.GetFlight().FlightPlan[i].Type != Waypoint.WaypointType.Refuel)
					{
						num += item.Navigator.GetFlight().FlightPlan[i].Leg_Distance_Straight;
						continue;
					}
					flag = true;
					break;
				}
				if (!flag)
				{
					float num3 = item.Kinematics.MaxRange(bool_0: true, null, null);
					if (num > num3)
					{
						text = text + Environment.NewLine + "飞行编队" + Client.FlightPlanEditorWindow.SelectedFlight.Callsign + " The flightplan distance is " + num + " nm while the aircraft " + item.Name + " maximum range is " + num3;
					}
				}
			}
			if (Operators.CompareString(text, "", TextCompare: true) != 0)
			{
				if (DarkMessageBox.ShowError(text + Environment.NewLine + Environment.NewLine + Environment.NewLine + " Do you want to leave the flightplan as it is?", "ERROR AT LEAST ONE AIRCRAFT WILL CRASH", DarkDialogButton.YesNo) == DialogResult.Yes)
				{
					return false;
				}
				return true;
			}
		}
		return false;
	}

