	private void NewInterruptibleClient(List<ActiveUnit> list_0)
	{
		int Local_FlightIndex = 0;
		if (SelectedMission.FlightList.Count == 0)
		{
			return;
		}
		bool flag = true;
		foreach (Mission.Flight flight in SelectedMission.FlightList)
		{
			List<ActiveUnit> aUCurrentlyAssigned = flight.GetAUCurrentlyAssigned(SelectedMission, Client.CurrentScenario);
			if (aUCurrentlyAssigned.Count <= SelectedMission.FlightSize)
			{
				if (aUCurrentlyAssigned.Count < SelectedMission.FlightSize)
				{
					flag = false;
				}
				continue;
			}
			while (aUCurrentlyAssigned.Count == SelectedMission.FlightSize)
			{
				aUCurrentlyAssigned[aUCurrentlyAssigned.Count - 1].Navigator.ClearFlight();
				aUCurrentlyAssigned.RemoveAt(aUCurrentlyAssigned.Count - 1);
			}
			flag = true;
		}
		if (flag)
		{
			return;
		}
		list_0 = (from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
			where x.IsAircraft && Information.IsNothing(x.Navigator.GetFlight())
			select x).ToList();
		List<ActiveUnit> list = (from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
			where x.IsAircraft && !Information.IsNothing(x.Navigator.GetFlight())
			select x).ToList();
		List<KeyValuePair<string, int>> list2 = new List<KeyValuePair<string, int>>();
		foreach (Mission.Flight flight2 in SelectedMission.FlightList)
		{
			list2.Add(new KeyValuePair<string, int>(flight2.Callsign, 2));
		}
		string right = null;
		while (list_0.Count > 0)
		{
			bool flag2 = false;
			MissionEditor Me = this;
			int num = SelectedMission.FlightList.Count - 1;
			int num2;
			for (Local_FlightIndex = 0; Local_FlightIndex <= num; num2 = Local_FlightIndex, Local_FlightIndex = num2 + 1)
			{
				if (list_0.Count == 0)
				{
					break;
				}
				string left = "";
				if (list.Count > 0)
				{
					ActiveUnit activeUnit = list.Where((ActiveUnit x) => Operators.CompareString(x.Navigator.GetFlight().Callsign, Me.SelectedMission.FlightList[Local_FlightIndex].Callsign, TextCompare: true) == 0).FirstOrDefault();
					if (activeUnit == null)
					{
						continue;
					}
					if (activeUnit.IsAircraft)
					{
						Aircraft aircraft = (Aircraft)activeUnit;
						if (aircraft.AirOps.CurrentHostUnit != null)
						{
							left = aircraft.AirOps.CurrentHostUnit.Name;
						}
					}
				}
				ActiveUnit Local_AU = list_0.Where((ActiveUnit x) => x.IsAircraft && ((Aircraft)x).Int32_0 == Me.SelectedMission.FlightList[Local_FlightIndex].int_0).FirstOrDefault();
				if (Local_AU == null)
				{
					continue;
				}
				if (Local_AU.IsAircraft && ((Aircraft)Local_AU).AirOps.CurrentHostUnit != null)
				{
					right = ((Aircraft)Local_AU).AirOps.CurrentHostUnit.Name;
				}
				if ((Operators.CompareString(left, right, TextCompare: true) == 0) | (Operators.CompareString(left, "", TextCompare: true) == 0))
				{
					int value = list2.Where((KeyValuePair<string, int> x) => Operators.CompareString(x.Key, Me.SelectedMission.FlightList[Local_FlightIndex].Callsign, TextCompare: true) == 0).First().Value;
					(from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
						where Operators.CompareString(x.ObjectID, Local_AU.ObjectID, TextCompare: true) == 0
						select x).First().SetFlight(SelectedMission.FlightList[Local_FlightIndex], value);
					list2.Remove(new KeyValuePair<string, int>(SelectedMission.FlightList[Local_FlightIndex].Callsign, value));
					list2.Add(new KeyValuePair<string, int>(SelectedMission.FlightList[Local_FlightIndex].Callsign, value + 1));
					list_0 = (from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
						where x.IsAircraft && Information.IsNothing(x.Navigator.GetFlight())
						select x).ToList();
					list = (from x in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
						where x.IsAircraft && !Information.IsNothing(x.Navigator.GetFlight())
						select x).ToList();
					flag2 = true;
				}
			}
			if (!flag2)
			{
				break;
			}
		}
	}

