	private void ConcatInterruptibleClient(object sender, EventArgs e)
	{
		if (!Information.IsNothing(SelectedMission))
		{
			((Strike)SelectedMission).AttackMethod = (Mission._AttackMethod)CB_AttackMethod.SelectedIndex;
		}
		if (CB_AttackMethod.SelectedIndex == 14)
		{
			CB_SplitDistance.Enabled = false;
		}
		else if (CB_AttackMethod.SelectedIndex <= 3)
		{
			CB_SplitDistance.Enabled = false;
		}
		else
		{
			CB_SplitDistance.Enabled = true;
		}
		SelectedMission.TimeSincePlayerNotification = 0;
	}

