	private void RemoveInterruptibleClient(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission) || SelectedMission.Category != Mission.MissionCategory.TaskPool)
		{
			return;
		}
		Scenario scenario_;
		Side side_;
		foreach (Mission package in ((TaskPool)SelectedMission).PackageList)
		{
			scenario_ = Client.CurrentScenario;
			side_ = Client.CurrentSide;
			PopInterruptibleDic(package, ref scenario_, ref side_, package.FlightSize);
			Client.CurrentSide = side_;
			package.TimeSincePlayerNotification = 0;
		}
		scenario_ = Client.CurrentScenario;
		side_ = Client.CurrentSide;
		Mission mission_ = SelectedMission;
		GameGeneral.CheckForMissionWakeup(ref scenario_, ref side_, ref mission_, bool_1: true, bool_2: false, bool_3: false, 0);
		SelectedMission = mission_;
		Client.CurrentSide = side_;
		RefreshAssignedUnits();
		RefreshUnassignedUnits();
		if (Client.AirTaskingOrderWindow.Visible)
		{
			Client.AirTaskingOrderWindow.LoadWindow();
		}
		Client.MustRefreshMainForm = true;
	}

	private void FindInterruptibleClient(object sender, EventArgs e)
	{
		if (TV_Missions.SelectedNodes.Count == 0)
		{
			return;
		}
		SelectedMission = (Mission)TV_Missions.SelectedNodes[0].Tag;
		if (Information.IsNothing(SelectedMission) || SelectedMission.Category != Mission.MissionCategory.TaskPool)
		{
			return;
		}
		foreach (Mission package in ((TaskPool)SelectedMission).PackageList)
		{
			Scenario scenario_ = Client.CurrentScenario;
			Side side_ = Client.CurrentSide;
			package.DeleteFlights(ref scenario_, ref side_);
			Client.CurrentSide = side_;
		}
		RefreshMissions();
		RefreshAssignedUnits();
		RefreshUnassignedUnits();
		Client.MustRefreshMainForm = true;
	}

