	private void UpdateInterruptibleClient(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission))
		{
			return;
		}
		if (!SelectedMission.UseFlightplans && SelectedMission.MissionClass == Mission._MissionClass.Ferry && ((((FerryMission)SelectedMission).Behavior != FerryMission.FerryMissionBehavior.OneWay) & CheckBox_UseFlightplans_Ferry.Checked))
		{
			DarkMessageBox.ShowError("Change the Mission Behaviour to enable Flightplans usage", "Flightplans are only supported for One Way Ferry Mission");
			CheckBox_UseFlightplans_Ferry.Checked = false;
			MoveInterruptibleVal();
			return;
		}
		SelectedMission.UseFlightplans = CheckBox_UseFlightplans_Ferry.Checked;
		if (!SelectedMission.UseFlightplans)
		{
			SelectedMission.UsePreGeneratedFlightplansOnly = false;
		}
		MoveInterruptibleVal();
	}

