	private void PrintInterruptibleClient()
	{
		try
		{
			if (callbackResolver)
			{
				callbackResolver = false;
				if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Patrol)
				{
					return;
				}
				if (!string.IsNullOrEmpty(TextBox_WingmanEngageDistance.Text) && Versioned.IsNumeric(TextBox_WingmanEngageDistance.Text))
				{
					if (Conversions.ToInteger(TextBox_WingmanEngageDistance.Text) <= 0)
					{
						((Patrol)SelectedMission).WingmanEngageDistance = 0;
						TextBox_WingmanEngageDistance.Text = "决不";
					}
					else
					{
						((Patrol)SelectedMission).WingmanEngageDistance = Conversions.ToInteger(TextBox_WingmanEngageDistance.Text);
					}
				}
				else
				{
					((Patrol)SelectedMission).WingmanEngageDistance = 0;
					TextBox_WingmanEngageDistance.Text = "决不";
				}
			}
			else
			{
				callbackResolver = false;
			}
		}
		catch (Exception projectError)
		{
			ProjectData.SetProjectError(projectError);
			callbackResolver = false;
			ProjectData.ClearProjectError();
		}
	}

