	private void ConnectInterruptibleDic(object sender, EventArgs e)
	{
		if (!Information.IsNothing(SelectedMission))
		{
			((Patrol)SelectedMission).ContinousCoverage_Enable = CheckBox_EnableContinousCoverage_Patrol.Checked;
			if (((Patrol)SelectedMission).ContinousCoverage_Enable)
			{
				SelectedMission.UsePreGeneratedFlightplansOnly = true;
			}
			RefreshAll();
		}
	}

	private void MoveInterruptibleDic(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission))
		{
			return;
		}
		((Patrol)SelectedMission).ContinousCoverage_QRAEnable = CheckBox_QRA_Enabled_Patrol.Checked;
		for (int i = SelectedMission.FlightList.Count - 1; i >= 0; i += -1)
		{
			Mission.Flight flight_ = SelectedMission.FlightList[0];
			if (flight_.Type != Mission._FlightType.FlightplanTemplate && flight_.Task == Mission._FlightTask.QRA)
			{
				Mission selectedMission = SelectedMission;
				Scenario scenario_ = Client.CurrentScenario;
				Side side_ = Client.CurrentSide;
				selectedMission.DeleteFlight(ref scenario_, ref side_, ref flight_, flight_.ObjectID);
				Client.CurrentSide = side_;
			}
		}
		RefreshAll();
	}

