	private void SetInterruptibleDic(object sender, EventArgs e)
	{
		if (TV_Missions.SelectedNodes.Count == 0)
		{
			return;
		}
		Client.MissionEditorWindow.ReadInterruptibleDic();
		if (SelectedMissionLink != null && SelectedMission != null)
		{
			if (SelectedMissionLink != null)
			{
				SelectedMission = SelectedMissionLink;
				SelectedMissionLink = null;
			}
		}
		else
		{
			if (TV_Missions.SelectedNodes[0] == null || Information.IsNothing(RuntimeHelpers.GetObjectValue(TV_Missions.SelectedNodes[0].Tag)))
			{
				Client.MissionEditorWindow.DisableInterruptibleDic();
				return;
			}
			if ((object)TV_Missions.Nodes[0].Tag.GetType().BaseType != typeof(Mission))
			{
				Client.MissionEditorWindow.DisableInterruptibleDic();
				return;
			}
			if (Operators.CompareString(SelectedMission.ObjectID, ((Mission)TV_Missions.SelectedNodes[0].Tag).ObjectID, TextCompare: true) == 0)
			{
				DisableInterruptibleDic();
				return;
			}
			SelectedMission = (Mission)TV_Missions.SelectedNodes[0].Tag;
		}
		RefreshAssignedUnits();
		RefreshUnassignedUnits();
		if (!TabControlNewGUI.TabPages[TabControlNewGUI.SelectedIndex].Visible)
		{
			TabControlNewGUI.SelectedTab = TabControlNewGUI.TabPages[0];
		}
		TV_Missions.EnsureVisible();
		Client.MissionEditorWindow.DisableInterruptibleDic();
		TV_Missions.Select();
	}

	private void FillInterruptibleDic(object sender, MouseEventArgs e)
	{
		Client.MissionEditorWindow.ReadInterruptibleDic();
		if (!Information.IsNothing(TV_Missions.SelectedNodes) && TV_Missions.SelectedNodes.Count != 0 && !Information.IsNothing(RuntimeHelpers.GetObjectValue(TV_Missions.SelectedNodes[0].Tag)))
		{
			if ((object)TV_Missions.SelectedNodes[0].Tag.GetType().BaseType == typeof(Mission))
			{
				if (Operators.CompareString(SelectedMission.ObjectID, ((Mission)TV_Missions.SelectedNodes[0].Tag).ObjectID, TextCompare: true) == 0)
				{
					Client.MissionEditorWindow.DisableInterruptibleDic();
					return;
				}
				SelectedMission = (Mission)TV_Missions.SelectedNodes[0].Tag;
				RefreshAssignedUnits();
				RefreshUnassignedUnits();
				Client.MissionEditorWindow.DisableInterruptibleDic();
				TV_Missions.Select();
			}
			else
			{
				Client.MissionEditorWindow.DisableInterruptibleDic();
			}
		}
		else
		{
			Client.MissionEditorWindow.DisableInterruptibleDic();
		}
	}

	private void CalculateInterruptibleDic(object sender, MouseEventArgs e)
	{
		if (TV_UnassignedUnits.SelectedNodes.Count > 0 && !Information.IsNothing(RuntimeHelpers.GetObjectValue(TV_UnassignedUnits.SelectedNodes[0].Tag)) && (object)TV_UnassignedUnits.SelectedNodes[0].Tag.GetType().BaseType.BaseType == typeof(ActiveUnit))
		{
			m_RulesIndexer = (ActiveUnit)TV_UnassignedUnits.SelectedNodes[0].Tag;
			ActiveUnit rulesIndexer = m_RulesIndexer;
			Mission selectedMission = SelectedMission;
			Mission.MissionAssignmentAttemptResult missionAssignmentAttemptResult_ = Mission.MissionAssignmentAttemptResult.None;
			rulesIndexer.Set_AssignedMissionOrPackage(selectedMission, bool_0: false, bool_1: false, ref missionAssignmentAttemptResult_);
			RefreshAssignedUnits();
			RefreshUnassignedUnits();
		}
	}

	private void PopInterruptibleDic(Mission mission_0, ref Scenario scenario_0, ref Side side_0, int int_0)
	{
		try
		{
			structResolver = true;
			EnableInterruptibleIssuer();
			structResolver = false;
			_ProcIndexer = true;
			IncludeInterruptibleIssuer();
			_ProcIndexer = false;
			if (mission_0.Category == Mission.MissionCategory.Package)
			{
				if (Information.IsNothing(mission_0.TakeOffTime) && Information.IsNothing(mission_0.TimeOnTarget) && DarkMessageBox.ShowWarning(base.Name + "：没有起飞时间或目标时间（TOT）此程序包已设置时间。您想创建没有航点时间的编队吗？如果没有，请按“否”并输入次数再重试。", "没有时间设定！", DarkDialogButton.YesNo) == DialogResult.No)
				{
					return;
				}
				if (!Information.IsNothing(mission_0.TakeOffTime))
				{
					DateTime? takeOffTime = mission_0.TakeOffTime;
					DateTime time = scenario_0.Time;
					if ((takeOffTime.HasValue ? new bool?(DateTime.Compare(takeOffTime.GetValueOrDefault(), time) < 0) : null).GetValueOrDefault())
					{
						DarkMessageBox.ShowWarning(base.Name + "：包的起飞时间早于当前的想定时间。请更正时间，然后重试。", string.Empty);
						return;
					}
				}
				if (!Information.IsNothing(mission_0.TimeOnTarget))
				{
					DateTime? timeOnTarget = mission_0.TimeOnTarget;
					DateTime time2 = scenario_0.Time;
					if ((timeOnTarget.HasValue ? new bool?(DateTime.Compare(timeOnTarget.GetValueOrDefault(), time2) <= 0) : null).GetValueOrDefault())
					{
						DarkMessageBox.ShowWarning(base.Name + "：程序包的Time-On-Target Time早于当前想定时间。请更正时间，然后重试。", string.Empty);
						return;
					}
				}
			}
			if (!Information.IsNothing(mission_0.MasterFlightList))
			{
				mission_0.MasterFlightList.Clear();
			}
			mission_0.TimeSincePlayerNotification = 0;
			GameGeneral.CheckForMissionWakeup(ref scenario_0, ref side_0, ref mission_0, bool_1: true, bool_2: false, bool_3: false, int_0);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 101382", "");
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

	private void InstantiateInterruptibleDic(object sender, EventArgs e)
	{
		if (ListBox_Targets.SelectedItems.Count <= 1)
		{
			int num = 1;
			if (ListBox_Targets.Items.Count > 5 && (System.Windows.Forms.Control.ModifierKeys & Keys.Shift) == Keys.Shift)
			{
				num = 5;
			}
			if (ListBox_Targets.Items.Count > 5 && (System.Windows.Forms.Control.ModifierKeys & Keys.Control) == Keys.Control)
			{
				num = 10;
			}
			int num2 = ListBox_Targets.SelectedIndices[0];
			if (num2 != -1 && num2 > 0)
			{
				if (num2 < num)
				{
					num = num2;
				}
				DarkListItem item = ListBox_Targets.SelectedItems[0];
				List<Module_Unit.Unit> list = ((Strike)SelectedMission).SpecificTargets.ToList();
				Module_Unit.Unit item2 = list[num2];
				ListBox_Targets.Items.RemoveAt(num2);
				list.RemoveAt(num2);
				num2 -= num;
				list.Insert(num2, item2);
				((Strike)SelectedMission).SpecificTargets = new HashSet<Module_Unit.Unit>(list);
				ListBox_Targets.Items.Insert(num2, item);
				ListBox_Targets.SelectItem(num2);
				Client.MustRefreshMainForm = true;
			}
		}
		else
		{
			DarkMessageBox.ShowWarning("一次只能重新排序一个目标", "一个目标一次！");
		}
	}

	private void CreateInterruptibleDic(object sender, EventArgs e)
	{
		if (ListBox_Targets.SelectedItems.Count <= 1)
		{
			int num = 1;
			if (ListBox_Targets.Items.Count > 5 && (System.Windows.Forms.Control.ModifierKeys & Keys.Shift) == Keys.Shift)
			{
				num = 5;
			}
			if (ListBox_Targets.Items.Count > 5 && (System.Windows.Forms.Control.ModifierKeys & Keys.Control) == Keys.Control)
			{
				num = 10;
			}
			int num2 = ListBox_Targets.SelectedIndices[0];
			if (num2 != -1)
			{
				if (num2 + num > ListBox_Targets.Items.Count)
				{
					num = ListBox_Targets.Items.Count - num2 - 1;
				}
				if (num2 < ListBox_Targets.Items.Count - num)
				{
					DarkListItem item = ListBox_Targets.SelectedItems[num2];
					List<Module_Unit.Unit> list = ((Strike)SelectedMission).SpecificTargets.ToList();
					Module_Unit.Unit item2 = list[num2];
					ListBox_Targets.Items.RemoveAt(num2);
					list.RemoveAt(num2);
					num2 += num;
					list.Insert(num2, item2);
					((Strike)SelectedMission).SpecificTargets = new HashSet<Module_Unit.Unit>(list);
					ListBox_Targets.Items.Insert(num2, item);
					ListBox_Targets.SelectItem(num2);
					Client.MustRefreshMainForm = true;
				}
			}
		}
		else
		{
			DarkMessageBox.ShowWarning("一次只能重新排序一个目标", "一个目标一次！");
		}
	}

	[DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
	private static extern IntPtr SendMessage(IntPtr intptr_0, int int_0, IntPtr intptr_1, IntPtr intptr_2);

	private void ReadInterruptibleDic()
	{
		try
		{
			SendMessage(base.Handle, 11, new IntPtr(0), IntPtr.Zero);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 200372", exception_.Message);
