	private void PrepareInterruptibleDic(object sender, EventArgs e)
	{
		if (TV_AssignedUnits.SelectedNodes.Count == 0)
		{
			return;
		}
		DarkTreeNode darkTreeNode = TV_AssignedUnits.SelectedNodes[0];
		ActiveUnit activeUnit = null;
		if (Information.IsNothing(darkTreeNode))
		{
			return;
		}
		if (darkTreeNode.Tag != null)
		{
			if (darkTreeNode.Tag is ScenarioObject && ((ScenarioObject)darkTreeNode.Tag).IsActiveUnit)
			{
				activeUnit = (ActiveUnit)darkTreeNode.Tag;
			}
			else if (darkTreeNode.Tag.ToString().StartsWith("#FLIGHT#") && darkTreeNode.Nodes.Count > 0 && darkTreeNode.Nodes.FirstOrDefault().Tag is ScenarioObject && ((ScenarioObject)darkTreeNode.Nodes.FirstOrDefault().Tag).IsActiveUnit)
			{
				activeUnit = (ActiveUnit)darkTreeNode.Nodes.FirstOrDefault().Tag;
			}
			if (activeUnit != null)
			{
				if (!activeUnit.IsOperating() && activeUnit.Navigator.HasFlight)
				{
					Client.SelectedWaypoint = activeUnit.Navigator.GetFlight().FlightPlan.FirstOrDefault();
				}
				ItemExporter.ConnectInterruptibleTemplate.MainForm.SetMapCenter(bool_0: true, new GeoPoint(activeUnit.GetLongitude(), activeUnit.GetLatitude()));
				Client.SelectThisUnit(activeUnit, bool_0: true);
			}
		}
		m_WrapperResolver = true;
	}

	private void ReflectInterruptibleDic(object sender, EventArgs e)
	{
		if (TV_UnassignedUnits.SelectedNodes.Count != 0)
		{
			DarkTreeNode darkTreeNode = TV_UnassignedUnits.SelectedNodes[0];
			if (darkTreeNode.Tag != null && darkTreeNode.Tag is ScenarioObject && ((ScenarioObject)darkTreeNode.Tag).IsActiveUnit)
			{
				ActiveUnit activeUnit = (ActiveUnit)darkTreeNode.Tag;
				ItemExporter.ConnectInterruptibleTemplate.MainForm.SetMapCenter(bool_0: true, new GeoPoint(activeUnit.GetLongitude(), activeUnit.GetLatitude()));
				Client.SelectThisUnit(activeUnit, bool_0: true);
			}
			m_WrapperResolver = false;
		}
	}

