	private void CloneInterruptibleConsumer(int int_0 = -1)
	{
		if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
		{
			Strike strike = (Strike)SelectedMission;
			if (int_0 == -1)
			{
				strike.FocusEntirelyOnStrikeTargets = !strike.FocusEntirelyOnStrikeTargets;
			}
			else
			{
				strike.FocusEntirelyOnStrikeTargets = int_0 != 0;
			}
			DeleteInterruptibleConsumer();
		}
	}

	private void ConnectInterruptibleConsumer(int int_0 = -1)
	{
		if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
		{
			Strike strike = (Strike)SelectedMission;
			if (int_0 == -1)
			{
				strike.FlightPlanPreventShotgunRTB = !strike.FlightPlanPreventShotgunRTB;
			}
			else
			{
				strike.FlightPlanPreventShotgunRTB = int_0 != 0;
			}
			DestroyInterruptibleConsumer();
		}
	}

	private void MoveInterruptibleConsumer(int int_0 = -1)
	{
		if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
		{
			Strike strike = (Strike)SelectedMission;
			if (int_0 == -1)
			{
				strike.RTB_When_Target_Destroyed = !strike.RTB_When_Target_Destroyed;
			}
			else
			{
				strike.RTB_When_Target_Destroyed = int_0 != 0;
			}
			AddInterruptibleConsumer();
		}
	}

	private void DeleteInterruptibleConsumer()
	{
		if (Information.IsNothing(SelectedMission) || SelectedMission.MissionClass != Mission._MissionClass.Strike)
		{
			return;
		}
		Strike strike = (Strike)SelectedMission;
		string text;
		if (strike.FocusEntirelyOnStrikeTargets)
		{
			text = "聚焦攻击目标";
			if (strike.TargetCount > 1)
			{
				text += "s";
			}
			RunInterruptibleDescriptor().SetToolTip(StrikeMissionFocus_Toggle, "The members of the strike team will ignore all other opportunity targets. Escorts will scramble as expected.");
		}
		else
		{
			text = "遇到机会目标时分散";
			RunInterruptibleDescriptor().SetToolTip(StrikeMissionFocus_Toggle, "The members of the strike team and the escorts may be distracted from the targets when encountering an opportunity target.");
		}
		StrikeMissionFocus_Toggle.Text = text;
	}

	private void AddInterruptibleConsumer()
	{
		if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
		{
			if (((Strike)SelectedMission).RTB_When_Target_Destroyed)
			{
				RunInterruptibleDescriptor().SetToolTip(StrikeRTBaftermissioncompleted_Toggle, "All aircraft will return to base upon destroying all targets.");
				StrikeRTBaftermissioncompleted_Toggle.Text = "目标被摧毁时 : 返回基地";
			}
			else
			{
				RunInterruptibleDescriptor().SetToolTip(StrikeRTBaftermissioncompleted_Toggle, "The mission will continue after the targets have been destroyed.");
				StrikeRTBaftermissioncompleted_Toggle.Text = "目标被摧毁时 : 继续任务";
			}
			SelectedMission.TimeSincePlayerNotification = 0;
		}
	}

	private void DestroyInterruptibleConsumer()
	{
		if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
		{
			if (((Strike)SelectedMission).FlightPlanPreventShotgunRTB)
			{
				RunInterruptibleDescriptor().SetToolTip(ButtonEngageUntil, "Fire the mission weapons then RTB.");
				ButtonEngageUntil.Text = "交战直至仅剩机炮";
			}
			else
			{
				RunInterruptibleDescriptor().SetToolTip(ButtonEngageUntil, "Continue to engage until all available weapons are used.");
				ButtonEngageUntil.Text = "交战直至任务武器耗尽用";
			}
			SelectedMission.TimeSincePlayerNotification = 0;
		}
	}

