	private void CallInterruptibleConsumer()
	{
		try
		{
			if (Information.IsNothing(m_RulesIndexer))
			{
				return;
			}
			LabelValue_MultiMissionName.Text = m_RulesIndexer.Name;
			LabelValue_CurrentStatus.Text = Misc.ToEnglishString(m_RulesIndexer.Status, m_RulesIndexer);
			CBLockToActive.CheckedChanged -= IncludeInterruptibleConsumer;
			CBLockToActive.Checked = m_RulesIndexer.AllowMultiMission;
			CBLockToActive.CheckedChanged += IncludeInterruptibleConsumer;
			DGV_Multimission.Items.Clear();
			Mission mission = m_RulesIndexer.AssignedMissionOrPackage();
			if (mission != null)
			{
				DGV_Multimission.Items.Add(new DarkListItem(mission.Name + " (Active)"));
				DGV_Multimission.Items.ElementAt(DGV_Multimission.Items.Count - 1).TextColor = Color.FromArgb(255, 144, 240, 144);
				DGV_Multimission.Items.ElementAt(DGV_Multimission.Items.Count - 1).Tag = mission;
			}
			foreach (Mission value in m_RulesIndexer.AssignedMissionsQueue.Values)
			{
				DGV_Multimission.Items.Add(new DarkListItem(value.Name));
				DGV_Multimission.Items.ElementAt(DGV_Multimission.Items.Count - 1).Tag = value;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 2006D32", exception_.Message);
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

