	private void GetInterruptibleConsumer(object sender, EventArgs e)
	{
		if (SelectedMission == null || SelectedMission.Category == Mission.MissionCategory.TaskPool)
		{
			return;
		}
		ActiveUnit secondaryAirBase = SelectedMission.SecondaryAirBase;
		List<ActiveUnit> list_ = new List<ActiveUnit>();
		List<ReferencePoint> list_2 = null;
		List<Zone> list_3 = null;
		UnitSelection.CallDialog(bool_0: false, ref list_, ref list_2, ref list_3, UnitSelection.UnitSelectionConfig.DefaultAirbase(bool_0: false), bool_1: false);
		if (list_.Count <= 0)
		{
			SelectedMission.SecondaryAirBase = null;
		}
		else
		{
			SelectedMission.SecondaryAirBase = list_.ElementAt(0);
		}
		WriteInterruptibleConsumer();
		if (secondaryAirBase == SelectedMission.SecondaryAirBase)
		{
			return;
		}
		foreach (Mission.Flight Local_theFlight in SelectedMission.FlightList)
		{
			if (SelectedMission.SecondaryAirBase == null)
			{
				Local_theFlight.LandingLocation_HostUnitObjectID = "";
				Local_theFlight.LandingLocation_HostUnitObjectName = "";
			}
			else
			{
				Local_theFlight.LandingLocation_HostUnitObjectID = SelectedMission.SecondaryAirBase.ObjectID;
				Local_theFlight.LandingLocation_HostUnitObjectName = SelectedMission.SecondaryAirBase.Name;
			}
			if (Local_theFlight.FlightPlan.Count() <= 0)
			{
				continue;
			}
			Waypoint waypoint = null;
			Waypoint waypoint2 = null;
			Waypoint[] flightPlan = Local_theFlight.FlightPlan;
			Waypoint[] array = flightPlan;
			foreach (Waypoint waypoint3 in array)
			{
				if (waypoint3.Type == Waypoint.WaypointType.LandingMarshal)
				{
					waypoint2 = waypoint3;
				}
				else if (waypoint3.Type == Waypoint.WaypointType.Land)
				{
					waypoint = waypoint3;
					break;
				}
			}
			if (waypoint != null && SelectedMission.SecondaryAirBase != null)
			{
				waypoint.Latitude = SelectedMission.SecondaryAirBase.GetLatitude();
				waypoint.Longitude = SelectedMission.SecondaryAirBase.GetLongitude();
				if (waypoint2 != null)
				{
					Geopoint_Struct landingQueueAssemblyPoint = SelectedMission.SecondaryAirBase.AirOps.LandingQueueAssemblyPoint;
					waypoint2.Latitude = landingQueueAssemblyPoint.Latitude;
					waypoint2.Longitude = landingQueueAssemblyPoint.Longitude;
				}
				List<ActiveUnit> list = new List<ActiveUnit>();
				list.AddRange((from theAU in Module_Mission.AssetTokenizer(SelectedMission, Client.CurrentScenario)
					where theAU.Navigator.HasFlight && theAU.IsAircraft && theAU.IsOperating() && theAU.Navigator.GetFlight() == Local_theFlight
					select theAU).ToList());
				foreach (Aircraft item in list)
				{
					if (Operators.CompareString(Local_theFlight.LandingLocation_HostUnitObjectID, item.AirOps.GetAssignedHostUnit().ObjectID, TextCompare: true) != 0)
					{
						if (Client.CurrentScenario.ActiveUnits.ContainsKey(Local_theFlight.LandingLocation_HostUnitObjectID))
						{
							item.AirOps.SetAssignedHostUnit(bool_0: false, Client.CurrentScenario.ActiveUnits[Local_theFlight.LandingLocation_HostUnitObjectID]);
						}
						else if (Debugger.IsAttached)
						{
							Debugger.Break();
						}
					}
				}
				continue;
			}
			Interaction.MsgBox("错误！在飞行计划中找不到陆地航点！");
			break;
		}
	}

