	private void CalculateInterruptibleConsumer()
	{
		if (SelectedMission == null || SelectedMission.MissionClass != Mission._MissionClass.Cargo)
		{
			return;
		}
		List<int> list = new List<int>();
		if (List_CargoItems.SelectedIndices.Count <= 0)
		{
			list.Add(-1);
		}
		else
		{
			list.Add(List_CargoItems.SelectedIndices.ElementAt(0));
		}
		List_CargoItems.Items.Clear();
		CargoMission cargoMission = (CargoMission)SelectedMission;
		List<CargoManifestItem> list2 = null;
		List<CargoManifestItem> list_ = null;
		bool enabled = false;
		string text = "分配的货物";
		ActiveUnit activeUnit_ = null;
		if ((uint)(cargoMission.CreationMode - 2) <= 1u)
		{
			if (cargoMission.CargoToUnload != null)
			{
				list2 = cargoMission.CargoToUnload;
			}
			text = "Landing Planner generated Cargo mission (CANNOT BE EDITED)";
		}
		else if (List_CargoSources.SelectedIndices.Count <= 0)
		{
			text = "未指定货物来源";
		}
		else
		{
			activeUnit_ = (ActiveUnit)List_CargoSources.SelectedItems[0].Tag;
			list2 = Cargo.GenerateCargoManifest(activeUnit_, bool_0: false, bool_1: false, bool_2: true);
			enabled = true;
		}
		if (list2 != null)
		{
			int num = 0;
			string text2 = "";
			bool moveAllCargo = cargoMission.MoveAllCargo;
			bool @checked;
			if (@checked = CB_CargoUseConsolidatedItemList.Checked)
			{
				list_ = new List<CargoManifestItem>(list2);
				list2 = Cargo.GenerateCargoManifest(activeUnit_, bool_0: false, bool_1: true, bool_2: true);
			}
			foreach (CargoManifestItem item in list2)
			{
				num = 0;
				if (moveAllCargo)
				{
					num = item.quantity;
				}
				else if (@checked)
				{
					foreach (CargoManifestItem item2 in cargoMission.CargoToUnload)
					{
						if (item2.IsMatch(item) && CargoManifestItem.FindMatch(item2, list_) != null)
						{
							num += item2.quantity;
						}
					}
				}
				else
				{
					CargoManifestItem cargoManifestItem = CargoManifestItem.FindMatch(item, cargoMission.CargoToUnload);
					if (cargoManifestItem != null)
					{
						num = cargoManifestItem.quantity;
					}
				}
				if (item.quantity < 2)
				{
					text2 = " " + num + "/1  ";
				}
				else
				{
					text2 = num + "/" + item.quantity;
					if (num < 10)
					{
						text2 = " " + text2;
					}
