	private void PublishInterruptibleConsumer()
	{
		try
		{
			if (SelectedMission == null)
			{
				Panel_Escort_Emcon_WRA.Controls.Clear();
				EMCON_WRA_Panel.Controls.Clear();
				EMCON_WRA_Mission = "";
				return;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception exception_ = ex;
			exception_?.Data.Add("Error at 0098385763", "");
			GameGeneral.WriteExceptionsToLog(ref exception_);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
		if (TabControlNewGUI.SelectedIndex == 3)
		{
			try
			{
				if (SelectedMission != null && !Information.IsNothing(SelectedMission))
				{
					theDoctrineForm.Subject = SelectedMission;
					theDoctrineForm.isEscorts = false;
					theDoctrineForm = AwakeInterruptibleConsumer(theDoctrineForm);
					if (EMCON_WRA_Panel.Controls.Count == 0)
					{
						EMCON_WRA_Panel.Controls.Add(theDoctrineForm);
					}
					theDoctrineForm.Show();
					EMCON_WRA_Mission = SelectedMission.ObjectID;
					theDoctrineForm.DefineSingleton();
				}
				return;
			}
			catch (Exception ex2)
			{
				ProjectData.SetProjectError(ex2);
				Exception exception_2 = ex2;
				exception_2?.Data.Add("Error at 0098385764", "");
				GameGeneral.WriteExceptionsToLog(ref exception_2);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
				return;
			}
		}
		if (TabControlNewGUI.SelectedIndex != 4)
		{
			return;
		}
		try
		{
			if (SelectedMission != null)
			{
				Panel_Escort_Emcon_WRA.Controls.Clear();
				if (!Information.IsNothing(SelectedMission) && SelectedMission.MissionClass == Mission._MissionClass.Strike)
				{
					theDoctrineForm.Subject = SelectedMission;
					theDoctrineForm.isEscorts = true;
					theDoctrineForm = AwakeInterruptibleConsumer(theDoctrineForm);
					Panel_Escort_Emcon_WRA.Controls.Add(theDoctrineForm);
					theDoctrineForm.Show();
					EMCON_WRA_Escort = SelectedMission.ObjectID;
				}
			}
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception exception_3 = ex3;
			exception_3?.Data.Add("Error at 0098385765", "");
			GameGeneral.WriteExceptionsToLog(ref exception_3);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}

