	private void ResetInterruptibleConsumer(object sender, EventArgs e)
	{
		if (Information.IsNothing(SelectedMission))
		{
			return;
		}
		FlightPlanEditor.DoNotNotifyFlightError = true;
		Client.FlightPlanEditorWindow.SelectedMission = SelectedMission;
		if (SelectedMission.FlightList.Count <= 0)
		{
			Client.FlightPlanEditorWindow.SelectedFlight = null;
		}
		else
		{
			Client.FlightPlanEditorWindow.SelectedFlight = SelectedMission.FlightList[0];
		}
		if (Client.FlightPlanEditorWindow.Visible)
		{
			Client.FlightPlanEditorWindow.ReloadWindow();
			Client.FlightPlanEditorWindow.BringToFront();
		}
		else
		{
			try
			{
				Client.FlightPlanEditorWindow.Show();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception exception_ = ex;
				exception_?.Data.Add("Error at 23453209804014777", "");
				GameGeneral.WriteExceptionsToLog(ref exception_);
				if (Debugger.IsAttached)
				{
					Debugger.Break();
				}
				ProjectData.ClearProjectError();
			}
		}
		FlightPlanEditor.DoNotNotifyFlightError = false;
	}

	private void MapInterruptibleConsumer(object sender, EventArgs e)
	{
		Mission._MissionClass? missionClass = SelectedMission?.MissionClass;
		byte? b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 1) : null).GetValueOrDefault())
		{
			WriteInterruptibleClient(null, null);
			return;
		}
		b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 2) : null).GetValueOrDefault())
		{
			InvokeInterruptibleClient(null, null);
			return;
		}
		b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 3) : null).GetValueOrDefault())
		{
			ExcludeInterruptibleClient(null, null);
			return;
		}
		b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 5) : null).GetValueOrDefault())
		{
			ChangeInterruptibleClient(null, null);
			return;
		}
		b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 6) : null).GetValueOrDefault())
		{
			CheckInterruptibleClient(null, null);
			return;
		}
		b = (byte?)missionClass;
		if ((b.HasValue ? new bool?(b.GetValueOrDefault() == 4) : null).GetValueOrDefault())
		{
			SearchInterruptibleClient(null, null);
		}
	}

